function price(order: Order) {
  return order.items.reduce((s, i) => s + i.price * (1 - i.discount), 0) +
         order.items.reduce((s, i) => s + i.tax, 0);
}

// Version B
function price(order: Order) {
  const items = order.items;
  const subtotal = items.reduce((s, i) => s + i.price * (1 - i.discount), 0);
  const taxes = items.reduce((s, i) => s + i.tax, 0);
  return subtotal + taxes;
}
